package com.aicharacter.v3;import org.json.JSONObject;
public final class CatState {
 public String areaId="home_shelter",sleepAreaId="",sleepMode="AWAKE",attachedToEntity="",attachmentContext="",sleepDestination="",sleepTargetEntity="",approachTarget="";
 public float x=320f;public boolean awake=true,carryKnownByGirl=false;public double energy=78,sleepiness=20;public long lastPlayerActiveAt=0L,sleepStartedAt=0L,actualSleepStartedAt=0L,lastUpdatedAt=0L;public String lastSleepPlanReason="";public int homeSleeps=0,safeSpotSleeps=0,nearGirlSleeps=0,withGirlSleeps=0;
 public JSONObject toJson(){JSONObject j=new JSONObject();try{j.put("areaId",areaId);j.put("sleepAreaId",sleepAreaId);j.put("sleepMode",sleepMode);j.put("attachedToEntity",attachedToEntity);j.put("attachmentContext",attachmentContext);j.put("sleepDestination",sleepDestination);j.put("sleepTargetEntity",sleepTargetEntity);j.put("approachTarget",approachTarget);j.put("carryKnownByGirl",carryKnownByGirl);j.put("x",x);j.put("awake",awake);j.put("energy",energy);j.put("sleepiness",sleepiness);j.put("lastPlayerActiveAt",lastPlayerActiveAt);j.put("sleepStartedAt",sleepStartedAt);j.put("actualSleepStartedAt",actualSleepStartedAt);j.put("lastUpdatedAt",lastUpdatedAt);j.put("lastSleepPlanReason",lastSleepPlanReason);j.put("homeSleeps",homeSleeps);j.put("safeSpotSleeps",safeSpotSleeps);j.put("nearGirlSleeps",nearGirlSleeps);j.put("withGirlSleeps",withGirlSleeps);}catch(Exception ignored){}return j;}
 public static CatState fromJson(JSONObject j,float legacyX,long now){CatState c=new CatState();c.x=legacyX;c.lastPlayerActiveAt=now;c.lastUpdatedAt=now;if(j!=null){c.areaId=j.optString("areaId",c.areaId);c.sleepAreaId=j.optString("sleepAreaId","");c.sleepMode=j.optString("sleepMode","AWAKE");c.attachedToEntity=j.optString("attachedToEntity","");c.attachmentContext=j.optString("attachmentContext","");c.sleepDestination=j.optString("sleepDestination",c.sleepAreaId);c.sleepTargetEntity=j.optString("sleepTargetEntity","");c.approachTarget=j.optString("approachTarget","");c.carryKnownByGirl=j.optBoolean("carryKnownByGirl","girl".equals(c.attachedToEntity));c.x=(float)j.optDouble("x",legacyX);c.awake=j.optBoolean("awake",true);c.energy=j.optDouble("energy",78);c.sleepiness=j.optDouble("sleepiness",20);c.lastPlayerActiveAt=j.optLong("lastPlayerActiveAt",now);c.sleepStartedAt=j.optLong("sleepStartedAt",0);c.actualSleepStartedAt=j.optLong("actualSleepStartedAt",legacyActualSleepStart(c));c.lastUpdatedAt=j.optLong("lastUpdatedAt",now);c.lastSleepPlanReason=j.optString("lastSleepPlanReason","");c.homeSleeps=j.optInt("homeSleeps",0);c.safeSpotSleeps=j.optInt("safeSpotSleeps",0);c.nearGirlSleeps=j.optInt("nearGirlSleeps",0);c.withGirlSleeps=j.optInt("withGirlSleeps",0);}return c;}
 private static long legacyActualSleepStart(CatState c){if(c.sleepStartedAt<=0)return 0;String m=c.sleepMode==null?"":c.sleepMode;return m.startsWith("TRAVELLING_TO_")||"APPROACHING_GIRL".equals(m)||"RESTING_WHERE_STRANDED".equals(m)?0:c.sleepStartedAt;}
}
